'use strict';
// SAM v2 strict-profile spec of the checkout core in src/host.impl.ts.
//
// Three carts (a, b, c) compete for the inventory's 2 units. A cart never has
// more than one message of its own in transit (Reserve -> Reserved/OutOfStock
// -> Charge -> Charged/Declined, or a trailing Release), so the network is
// modelled as one `msg_<cart>` slot per cart, and DELIVER {cart} delivers that
// slot. Since any slot can be delivered at any time, every arrival order is
// explored. status 'none' = never opened.

const { createInstance } = require('@cognitive-fab/sam-pattern');

const instance = createInstance({ strict: true, hasAsyncActions: false });

const CARTS = ['a', 'b', 'c'];
const MAX_ITEMS = 2;
const CHARGE_CAP = 4;

const INITIAL_STATE = { available: 2, reserved: 0, charged: 0, declining: false };
for (const c of CARTS) Object.assign(INITIAL_STATE, { ['status_' + c]: 'none', ['items_' + c]: 0, ['msg_' + c]: 'none' });

const modelShape = {
  available: { type: 'number' },
  reserved: { type: 'number' },
  charged: { type: 'number' },
  declining: { type: 'boolean' },
};
for (const c of CARTS) {
  modelShape['status_' + c] = { type: 'string' };
  modelShape['items_' + c] = { type: 'number' };
  modelShape['msg_' + c] = { type: 'string' };
}
