tool_use_result.originalFile:
'use strict';
// SAM v2 strict-profile spec of the checkout core in src/host.impl.ts.
//
// Three carts (a, b, c) compete for the inventory's 2 units. A cart never has
// more than one message of its own in transit (Reserve -> Reserved/OutOfStock
// -> Charge -> Charged/Declined, or a trailing Release), so the network is
// modelled as one `msg_<cart>` slot per cart, and DELIVER {cart} delivers that
// slot. Since any slot can be delivered at any time, every arrival order is
// explored. status 'none' = never opened.

const { createInstance } = require('@cognitive-fab/sam-pattern');

const instance = createInstance({ strict: true, hasAsyncActions: false });

const CARTS = ['a', 'b', 'c'];
const MAX_ITEMS = 2;
const CHARGE_CAP = 4;

const INITIAL_STATE = { available: 2, reserved: 0, charged: 0, declining: false };
for (const c of CARTS) Object.assign(INITIAL_STATE, { ['status_' + c]: 'none', ['items_' + c]: 0, ['msg_' + c]: 'none' });

const modelShape = {
  available: { type: 'number' },
  reserved: { type: 'number' },
  charged: { type: 'number' },
  declining: { type: 'boolean' },
};
for (const c of CARTS) {
  modelShape['status_' + c] = { type: 'string' };
  modelShape['items_' + c] = { type: 'number' };
  modelShape['msg_' + c] = { type: 'string' };
}
const KEYS = Object.keys(modelShape);

// Assign the changed keys, frame the rest.
const commit = (next, unchanged, changes) => {
  for (const [k, v] of Object.entries(changes)) next[k] = v;
  const rest = KEYS.filter((k) => !(k in changes));
  if (rest.length) unchanged(...rest);
};

const cartSchema = { cart: { type: 'string', required: true } };
const cartDomain = CARTS.map((cart) => ({ cart }));
// Each intent needs its own action function (SAM keys intents by function).
const cartAction = () => ({ action: (data = {}) => ({ ...data }), schema: cartSchema, domain: cartDomain });
const noData = () => ({ action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] });

const control = instance({
  initialState: { ...INITIAL_STATE },
  component: {
    modelShape,
    actions: {
      OPEN: cartAction(),
      ADD: cartAction(),
      CHECKOUT: cartAction(),
      CANCEL: cartAction(),
      DECLINE_CARDS: noData(),
      ACCEPT_CARDS: noData(),
      DELIVER: cartAction(),
    },
    acceptors: {
      OPEN: (model) => (p, { reject, next, unchanged }) => {
        const c = p.cart;
        if (model['status_' + c] !== 'none') return reject('cart-exists');
        commit(next, unchanged, { ['status_' + c]: 'open' });
      },
      ADD: (model) => (p, { reject, next, unchanged }) => {
        const c = p.cart;
        if (model['status_' + c] !== 'open') return reject('not-open');
        if (model['items_' + c] >= MAX_ITEMS) return reject('cart-full');
        commit(next, unchanged, { ['items_' + c]: model['items_' + c] + 1 });
      },
      CHECKOUT: (model) => (p, { reject, next, unchanged }) => {
        const c = p.cart;
        if (model['status_' + c] !== 'open') return reject('not-open');
        if (model['items_' + c] < 1) return reject('cart-empty');
        commit(next, unchanged, { ['status_' + c]: 'reserving', ['msg_' + c]: 'Reserve' });
      },
      CANCEL: (model) => (p, { reject, next, unchanged }) => {
        const c = p.cart;
        const s = model['status_' + c];
        if (s === 'open') return commit(next, unchanged, { ['status_' + c]: 'cancelled' });
        if (s === 'reserving') return commit(next, unchanged, { ['status_' + c]: 'cancelling' });
        return reject(s === 'paying' ? 'payment-in-progress' : 'cannot-cancel');
      },
      DECLINE_CARDS: (model) => (p, { reject, next, unchanged }) => {
        if (model.declining) return reject('already-declining');
        commit(next, unchanged, { declining: true });
      },
      ACCEPT_CARDS: (model) => (p, { reject, next, unchanged }) => {
        if (!model.declining) return reject('already-accepting');
        commit(next, unchanged, { declining: false });
      },
      DELIVER: (model) => (p, { reject, next, unchanged }) => {
        const c = p.cart;
        const S = 'status_' + c, M = 'msg_' + c;
        const s = model[S], items = model['items_' + c];
        switch (model[M]) {
          case 'Reserve': // at the inventory
            if (items <= model.available) {
              return commit(next, unchanged, {
                available: model.available - items, reserved: model.reserved + items, [M]: 'Reserved',
              });
            }
            return commit(next, unchanged, { [M]: 'OutOfStock' });
          case 'Reserved': // at the cart
            if (s === 'reserving') return commit(next, unchanged, { [S]: 'paying', [M]: 'Charge' });
            if (s === 'cancelling') return commit(next, unchanged, { [S]: 'cancelled', [M]: 'Release' });
            return commit(next, unchanged, { [M]: 'none' });
          case 'OutOfStock':
            if (s === 'reserving') return commit(next, unchanged, { [S]: 'failed', [M]: 'none' });
            if (s === 'cancelling') return commit(next, unchanged, { [S]: 'cancelled', [M]: 'none' });
            return commit(next, unchanged, { [M]: 'none' });
          case 'Charge': // at the payment service
            if (model.declining || model.charged + items > CHARGE_CAP) return commit(next, unchanged, { [M]: 'Declined' });
            return commit(next, unchanged, { charged: model.charged + items, [M]: 'Charged' });
          case 'Charged':
            if (s === 'paying') return commit(next, unchanged, { [S]: 'paid', [M]: 'none' });
            return commit(next, unchanged, { [M]: 'none' });
          case 'Declined':
            if (s === 'paying') return commit(next, unchanged, { [S]: 'failed', [M]: 'none' });
            return commit(next, unchanged, { [M]: 'none' });
          case 'Release': // at the inventory
            return commit(next, unchanged, {
              reserved: model.reserved - items, available: model.available + items, [M]: 'none',
            });
          default:
            return reject('nothing-in-transit');
        }
      },
    },
    reactors: [],
  },
});

const { intents } = control;

const getState = () => instance({}).getState();
const setState = (snapshot) => { instance({}).setState(snapshot); };
const init = () => { setState(INITIAL_STATE); };

const actions = {
  OPEN: (data = {}) => intents.OPEN(data),
  ADD: (data = {}) => intents.ADD(data),
  CHECKOUT: (data = {}) => intents.CHECKOUT(data),
  CANCEL: (data = {}) => intents.CANCEL(data),
  DECLINE_CARDS: (data = {}) => intents.DECLINE_CARDS(data),
  ACCEPT_CARDS: (data = {}) => intents.ACCEPT_CARDS(data),
  DELIVER: (data = {}) => intents.DELIVER(data),
};

module.exports = { instance, init, actions, getState, setState };

prompt:
The brief has changed. Here is the change, in addition to everything the brief said before:

# Change 1: returns

A customer can now return a paid cart.

- `returnCart(cart)`: a paid cart becomes **returned**. It asks the payment service to refund it, with the message `Refund` and data `{ amount }` (its units), and gives its units back to the inventory with `Release`. Refused for a cart that is not paid.
- On `Refund`, the payment service subtracts `amount` from its total charged. It sends no answer.

`status` in the view can now also be `"returned"`. A returned cart accepts no command. Everything else is as before.

The host interface is now as follows, and `host.ts` has been updated to match.

```ts
// T4 after change 1, checkout with returns: the host interface every arm implements (PT13, S91).

/** A message sent by one part of the system to another, not yet delivered. */
export interface Message {
  id: string;
  from: string;
  to: string;
  action: string;
  data: Record<string, unknown>;
}

/** The network: nothing is delivered until deliver or deliverAll is called. */
export interface Network {
  /** Every message in transit, in no promised order. */
  inFlight(): Promise<Message[]>;
  /** Deliver one message in transit, by its id. */
  deliver(id: string): Promise<void>;
  /** Deliver every message in transit, and every message those deliveries send, until none is left. */
  deliverAll(): Promise<void>;
}

/** The outcome of a command: it took effect, or it was refused and changed nothing. */
export type Outcome = { ok: true } | { ok: false; reason: string };

export interface CartView {
  status: 'open' | 'reserving' | 'paying' | 'paid' | 'failed' | 'cancelling' | 'cancelled' | 'returned';
  items: number;
}

export interface Host extends Network {
  open(cart: string): Promise<Outcome>;
  add(cart: string): Promise<Outcome>;
  checkout(cart: string): Promise<Outcome>;
  cancel(cart: string): Promise<Outcome>;
  returnCart(cart: string): Promise<Outcome>;
  declineCards(): Promise<Outcome>;
  acceptCards(): Promise<Outcome>;
  /** The cart, or null when no cart has that id. */
  cart(cart: string): Promise<CartView | null>;
  stock(): Promise<{ available: number; reserved: number }>;
  payments(): Promise<{ charged: number; declining: boolean }>;
}

/** The module's default export: a factory of a fresh system, with the inventory, the payment service and no carts. */
export type CreateHost = () => Promise<Host>;
```

