import { test } from 'node:test';
import assert from 'node:assert/strict';
import create from '../src/host.impl.ts';

test('happy path', async () => {
  const h = await create();
  assert.deepEqual(await h.stock(), { available: 2, reserved: 0 });
  assert.deepEqual(await h.open('a'), { ok: true });
  assert.equal((await h.open('a')).ok, false);
  assert.equal((await h.checkout('a')).ok, false);
  await h.add('a');
  await h.add('a');
  assert.equal((await h.add('a')).ok, false);
  assert.deepEqual(await h.checkout('a'), { ok: true });
  assert.deepEqual(await h.cart('a'), { status: 'reserving', items: 2 });
  const msgs = await h.inFlight();
  assert.equal(msgs.length, 1);
  assert.deepEqual(
    { from: msgs[0].from, to: msgs[0].to, action: msgs[0].action, data: msgs[0].data },
    { from: 'a', to: 'inventory', action: 'Reserve', data: { from: 'a', qty: 2 } },
  );
  await h.deliver(msgs[0].id);
  assert.equal((await h.cart('a'))!.status, 'reserving');
  await h.deliver((await h.inFlight())[0].id);
  assert.equal((await h.cart('a'))!.status, 'paying');
  assert.equal((await h.cancel('a')).ok, false);
  await h.deliverAll();
  assert.deepEqual(await h.cart('a'), { status: 'paid', items: 2 });
  assert.deepEqual(await h.stock(), { available: 0, reserved: 2 });
  assert.deepEqual(await h.payments(), { charged: 2, declining: false });
});

test('unknown cart', async () => {
  const h = await create();
  assert.equal(await h.cart('x'), null);
  for (const f of [h.add, h.checkout, h.cancel]) assert.equal((await f('x')).ok, false);
});

test('out of stock', async () => {
  const h = await create();
  for (const c of ['a', 'b']) { await h.open(c); await h.add(c); await h.add(c); await h.checkout(c); }
  await h.deliverAll();
  const st = [(await h.cart('a'))!.status, (await h.cart('b'))!.status].sort();
  assert.deepEqual(st, ['failed', 'paid']);
  assert.deepEqual(await h.stock(), { available: 0, reserved: 2 });
});

test('declined releases', async () => {
  const h = await create();
  assert.deepEqual(await h.declineCards(), { ok: true });
  assert.equal((await h.declineCards()).ok, false);
  await h.open('a'); await h.add('a'); await h.checkout('a');
  await h.deliverAll();
  assert.equal((await h.cart('a'))!.status, 'failed');
  assert.deepEqual(await h.stock(), { available: 2, reserved: 0 });
  assert.deepEqual(await h.payments(), { charged: 0, declining: true });
  assert.deepEqual(await h.acceptCards(), { ok: true });
  assert.equal((await h.acceptCards()).ok, false);
});

