2	// SAM v2 strict-profile spec of the checkout core in src/host.impl.ts.
3	//
4	// Three carts (a, b, c) compete for the inventory's 2 units. A cart never has
5	// more than one message of its own in transit (Reserve -> Reserved/OutOfStock
6	// -> Charge -> Charged/Declined, or a trailing Release), so the network is
7	// modelled as one `msg_<cart>` slot per cart, and DELIVER {cart} delivers that
8	// slot. Since any slot can be delivered at any time, every arrival order is
9	// explored. status 'none' = never opened.
10	
11	const { createInstance } = require('@cognitive-fab/sam-pattern');
12	
