      if (!c) return refuse('no such cart');
      if (c.status !== 'open') return refuse(`cart is ${c.status}`);
      if (c.items >= MAX_ITEMS) return refuse('cart is full');
      c.items += 1;
      return ok;
    },
    async checkout(id) {
      const c = carts.get(id);
      if (!c) return refuse('no such cart');
