const cartDomain = CARTS.map((cart) => ({ cart }));
// Each intent needs its own action function (SAM keys intents by function).
const cartAction = () => ({ action: (data = {}) => ({ ...data }), schema: cartSchema, domain: cartDomain });
const noData = () => ({ action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] });

