  initialState: { ...INITIAL_STATE },
  component: {
    modelShape,
    actions: {
      OPEN: cartAction(),
      ADD: cartAction(),
      CHECKOUT: cartAction(),
      CANCEL: cartAction(),
      RETURN: cartAction(),
      RETRY: cartAction(),
      ABANDON: cartAction(),
      DECLINE_CARDS: noData(),
      ACCEPT_CARDS: noData(),
      DELIVER: cartAction(),
      DELIVER_REFUND: cartAction(),
    },
    acceptors: {
      OPEN: (model) => (p, { reject, next, unchanged }) => {
        const c = p.cart;
