      },
      RETRY: (model) => (p, { reject, next, unchanged }) => {
        const c = p.cart;
        if (model['status_' + c] !== 'declined') return reject('not-declined');
        commit(next, unchanged, { ['status_' + c]: 'paying', ['msg_' + c]: 'Charge' });
      },
      ABANDON: (model) => (p, { reject, next, unchanged }) => {
        const c = p.cart;
        if (model['status_' + c] !== 'declined') return reject('not-declined');
        commit(next, unchanged, { ['status_' + c]: 'failed', ['msg_' + c]: 'Release' });
