      ACCEPT_CARDS: (model) => (p, { reject, next, unchanged }) => {
        if (!model.declining) return reject('already-accepting');
        commit(next, unchanged, { declining: false });
      },
      DELIVER: (model) => (p, { reject, next, unchanged }) => {
        const c = p.cart;
        const S = 'status_' + c, M = 'msg_' + c;
        const s = model[S], items = model['items_' + c];
        switch (model[M]) {
          case 'Reserve': // at the inventory
            if (items <= model.available) {
              return commit(next, unchanged, {
                available: model.available - items, reserved: model.reserved + items, [M]: 'Reserved',
              });
            }
            return commit(next, unchanged, { [M]: 'OutOfStock' });
          case 'Reserved': // at the cart
            if (s === 'reserving') return commit(next, unchanged, { [S]: 'paying', [M]: 'Charge' });
            if (s === 'cancelling') return commit(next, unchanged, { [S]: 'cancelled', [M]: 'Release' });
            return commit(next, unchanged, { [M]: 'none' });
          case 'OutOfStock':
            if (s === 'reserving') return commit(next, unchanged, { [S]: 'failed', [M]: 'none' });
            if (s === 'cancelling') return commit(next, unchanged, { [S]: 'cancelled', [M]: 'none' });
            return commit(next, unchanged, { [M]: 'none' });
          case 'Charge': // at the payment service
            if (model.declining || model.charged + items > CHARGE_CAP) return commit(next, unchanged, { [M]: 'Declined' });
            return commit(next, unchanged, { charged: model.charged + items, [M]: 'Charged' });
          case 'Charged':
            if (s === 'paying') return commit(next, unchanged, { [S]: 'paid', [M]: 'none' });
            return commit(next, unchanged, { [M]: 'none' });
          case 'Declined':
            if (s === 'paying') return commit(next, unchanged, { [S]: 'declined', [M]: 'none' });
            return commit(next, unchanged, { [M]: 'none' });
          case 'Release': // at the inventory
            return commit(next, unchanged, {
              reserved: model.reserved - items, available: model.available + items, [M]: 'none',
            });
          default:
