// Rules the brief requires, over the state of spec/checkout.cjs.
const CARTS = ['a', 'b', 'c'];
const TOTAL = 2;

const status = (s, c) => s['status_' + c];
const items = (s, c) => s['items_' + c];
const msg = (s, c) => s['msg_' + c];
const refund = (s, c) => s['refund_' + c];
const sum = (f) => CARTS.reduce((n, c) => n + f(c), 0);
const quiet = (s) => CARTS.every((c) => msg(s, c) === 'none' && refund(s, c) === 'none');
const paidUnits = (s) => sum((c) => (status(s, c) === 'paid' ? items(s, c) : 0));

// Units the inventory holds for a cart: reserved and not yet given back.
const holds = (s, c) =>
  msg(s, c) === 'Reserved' || msg(s, c) === 'Release' || ['paying', 'paid'].includes(status(s, c));

// Units the payment service has charged a cart and not yet refunded.
const owes = (s, c) =>
  status(s, c) === 'paid' || (status(s, c) === 'paying' && msg(s, c) === 'Charged') || refund(s, c) === 'Refund';

export const stateInvariants = [
  { name: 'units-conserved', pred: (s) => s.available + s.reserved === TOTAL && s.available >= 0 && s.reserved >= 0 },
  { name: 'items-bounded', pred: (s) => CARTS.every((c) => items(s, c) >= 0 && items(s, c) <= 2) },
  { name: 'charge-cap', pred: (s) => s.charged >= 0 && s.charged <= 4 },
  // Conclusion of the brief: once quiet, reserved == charged == units of paid carts.
  { name: 'quiet-reserved-is-paid', pred: (s) => !quiet(s) || s.reserved === paidUnits(s) },
  { name: 'quiet-charged-is-paid', pred: (s) => !quiet(s) || s.charged === paidUnits(s) },
  // Stronger, at all times: the ledgers match the carts holding units / owing money.
  { name: 'reserved-matches-holders', pred: (s) => s.reserved === sum((c) => (holds(s, c) ? items(s, c) : 0)) },
  { name: 'charged-matches-owed', pred: (s) => s.charged === sum((c) => (owes(s, c) ? items(s, c) : 0)) },
  // Failed / cancelled / returned carts hold nothing once their Release (if any) is delivered.
  {
    name: 'ended-carts-hold-nothing',
    pred: (s) => CARTS.every((c) => !['failed', 'cancelled', 'returned'].includes(status(s, c)) || !holds(s, c) || msg(s, c) === 'Release'),
  },
  // Only a returned cart is ever owed a refund.
  { name: 'refund-only-when-returned', pred: (s) => CARTS.every((c) => refund(s, c) === 'none' || status(s, c) === 'returned') },
];

export const transitionInvariants = [
  {
    // A cart becomes paid only when its Charged answer arrives while paying.
    name: 'paid-only-after-charge',
    pred: (pre, action, data, post) =>
      CARTS.every((c) => status(pre, c) === 'paid' || status(post, c) !== 'paid'
        || (action === 'DELIVER' && data.cart === c && status(pre, c) === 'paying' && msg(pre, c) === 'Charged')),
  },
  {
    // A cart reaches paying only after the inventory reserved its units.
    name: 'paying-only-after-reserved',
    pred: (pre, action, data, post) =>
      CARTS.every((c) => status(pre, c) === 'paying' || status(post, c) !== 'paying'
        || (action === 'DELIVER' && data.cart === c && msg(pre, c) === 'Reserved')),
  },
  {
    // A cart is returned only from paid, by RETURN.
    name: 'returned-only-from-paid',
    pred: (pre, action, data, post) =>
      CARTS.every((c) => status(pre, c) === 'returned' || status(post, c) !== 'returned'
        || (action === 'RETURN' && data.cart === c && status(pre, c) === 'paid')),
  },
  {
    // Terminal statuses never change; paid changes only to returned.
    name: 'terminal-is-final',
    pred: (pre, _a, _d, post) =>
      CARTS.every((c) => (!['failed', 'cancelled', 'returned'].includes(status(pre, c)) || status(post, c) === status(pre, c))
        && (status(pre, c) !== 'paid' || ['paid', 'returned'].includes(status(post, c)))),
  },
  {
    name: 'items-frozen-after-checkout',
    pred: (pre, _a, _d, post) =>
      CARTS.every((c) => ['none', 'open'].includes(status(pre, c)) || items(post, c) === items(pre, c)),
  },
];

