// Rules the brief requires, over the state of spec/checkout.cjs.
const CARTS = ['a', 'b', 'c'];
const TOTAL = 2;

const status = (s, c) => s['status_' + c];
const items = (s, c) => s['items_' + c];
const msg = (s, c) => s['msg_' + c];
const release = (s, c) => s['release_' + c];
const refund = (s, c) => s['refund_' + c];
const sum = (f) => CARTS.reduce((n, c) => n + f(c), 0);
const quiet = (s) => CARTS.every((c) => msg(s, c) === 'none' && release(s, c) === 'none' && refund(s, c) === 'none');
const paidUnits = (s) => sum((c) => (status(s, c) === 'paid' ? items(s, c) : 0));
// Change 2: a declined cart keeps its units reserved until it retries or abandons.
const paidOrDeclinedUnits = (s) => sum((c) => (['paid', 'declined'].includes(status(s, c)) ? items(s, c) : 0));

// Units reserved for a cart that it has not started giving back.
const keeps = (s, c) => msg(s, c) === 'Reserved' || ['paying', 'paid', 'declined'].includes(status(s, c));
// Units the inventory still counts as reserved for a cart (incl. a Release in transit).
const holds = (s, c) => keeps(s, c) || release(s, c) === 'Release';

// Money the payment service has taken from a cart and not yet refunded.
const owes = (s, c) =>
  status(s, c) === 'paid'
  || (['paying', 'abandoning'].includes(status(s, c)) && msg(s, c) === 'Charged')
  || refund(s, c) === 'Refund';

const ENDED = ['failed', 'cancelled', 'returned', 'abandoning'];

export const stateInvariants = [
  { name: 'units-conserved', pred: (s) => s.available + s.reserved === TOTAL && s.available >= 0 && s.reserved >= 0 },
  { name: 'items-bounded', pred: (s) => CARTS.every((c) => items(s, c) >= 0 && items(s, c) <= 2) },
  { name: 'charge-cap', pred: (s) => s.charged >= 0 && s.charged <= 4 },
  // Conclusion of the brief: once quiet, reserved == units of paid (and, since
  // change 2, declined) carts, and charged == units of paid carts.
  { name: 'quiet-reserved-is-paid-or-declined', pred: (s) => !quiet(s) || s.reserved === paidOrDeclinedUnits(s) },
  { name: 'quiet-charged-is-paid', pred: (s) => !quiet(s) || s.charged === paidUnits(s) },
  // Stronger, at all times: the ledgers match the carts holding units / owing money.
  { name: 'reserved-matches-holders', pred: (s) => s.reserved === sum((c) => (holds(s, c) ? items(s, c) : 0)) },
  { name: 'charged-matches-owed', pred: (s) => s.charged === sum((c) => (owes(s, c) ? items(s, c) : 0)) },
  // Failed / cancelled / returned / abandoning carts have given back (or are giving back) their units.
  { name: 'ended-carts-keep-nothing', pred: (s) => CARTS.every((c) => !ENDED.includes(status(s, c)) || !keeps(s, c)) },
  // A refund is owed only to a cart that is returned, or failed after a late charge.
  { name: 'refund-only-when-ended', pred: (s) => CARTS.every((c) => refund(s, c) === 'none' || ['returned', 'failed'].includes(status(s, c))) },
  // A failed cart owes nothing once its refund (if any) is delivered.
  { name: 'failed-owes-nothing', pred: (s) => CARTS.every((c) => status(s, c) !== 'failed' || !owes(s, c) || refund(s, c) === 'Refund') },
];

const became = (pre, post, c, st) => status(pre, c) !== st && status(post, c) === st;
const by = (action, data, c, name) => action === name && data.cart === c;

export const transitionInvariants = [
  {
    // A cart becomes paid only when its Charged answer arrives while paying.
    name: 'paid-only-after-charge',
    pred: (pre, action, data, post) =>
      CARTS.every((c) => !became(pre, post, c, 'paid')
        || (by(action, data, c, 'DELIVER') && status(pre, c) === 'paying' && msg(pre, c) === 'Charged')),
  },
  {
    // A cart reaches paying only after the inventory reserved its units: on
    // Reserved, or by RETRY from declined (which still holds them).
    name: 'paying-only-after-reserved',
    pred: (pre, action, data, post) =>
      CARTS.every((c) => !became(pre, post, c, 'paying')
        || (by(action, data, c, 'DELIVER') && msg(pre, c) === 'Reserved')
        || (by(action, data, c, 'RETRY') && status(pre, c) === 'declined')),
  },
  {
    name: 'returned-only-from-paid',
    pred: (pre, action, data, post) =>
      CARTS.every((c) => !became(pre, post, c, 'returned') || (by(action, data, c, 'RETURN') && status(pre, c) === 'paid')),
  },
  {
    name: 'declined-only-after-decline',
    pred: (pre, action, data, post) =>
      CARTS.every((c) => !became(pre, post, c, 'declined')
        || (by(action, data, c, 'DELIVER') && status(pre, c) === 'paying' && msg(pre, c) === 'Declined')),
  },
  {
    // A declined cart leaves only by RETRY (to paying) or ABANDON (to failed).
    name: 'declined-exits',
    pred: (pre, action, data, post) =>
      CARTS.every((c) => status(pre, c) !== 'declined' || status(post, c) === 'declined'
        || (by(action, data, c, 'RETRY') && status(post, c) === 'paying')
        || (by(action, data, c, 'ABANDON') && status(post, c) === 'failed')),
  },
  {
    // A cart starts abandoning only by a payment timeout while paying.
    name: 'abandoning-only-after-timeout',
    pred: (pre, action, data, post) =>
      CARTS.every((c) => !became(pre, post, c, 'abandoning') || (by(action, data, c, 'PAYMENT_TIMEOUT') && status(pre, c) === 'paying')),
  },
  {
    // An abandoning cart leaves only to failed, on the payment service's answer;
    // it asks for a refund exactly when the answer was Charged.
    name: 'abandoning-exits',
    pred: (pre, action, data, post) =>
      CARTS.every((c) => status(pre, c) !== 'abandoning' || status(post, c) === 'abandoning'
        || (by(action, data, c, 'DELIVER') && status(post, c) === 'failed'
          && (refund(post, c) === 'Refund') === (msg(pre, c) === 'Charged'))),
  },
  {
    // Terminal statuses never change; paid changes only to returned.
    name: 'terminal-is-final',
    pred: (pre, _a, _d, post) =>
      CARTS.every((c) => (!['failed', 'cancelled', 'returned'].includes(status(pre, c)) || status(post, c) === status(pre, c))
        && (status(pre, c) !== 'paid' || ['paid', 'returned'].includes(status(post, c)))),
  },
  {
    name: 'items-frozen-after-checkout',
    pred: (pre, _a, _d, post) =>
      CARTS.every((c) => ['none', 'open'].includes(status(pre, c)) || items(post, c) === items(pre, c)),
  },
];

